package com.example.imageprocessor

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.nio.ByteBuffer
import java.nio.ByteOrder

// Native image processing via JNI - legacy path
external fun nativeResizeImage(inputBuffer: ByteArray, width: Int, height: Int, outputBuffer: ByteArray): Int

// Safe Kotlin-only resize (slower but bounds-checked)
fun safeResizeImage(inputBuffer: ByteArray, width: Int, height: Int): ByteArray {
    val outputSize = width * height * 4
    val output = ByteArray(outputSize)
    // Pure Kotlin implementation with bounds checking
    for (i in 0 until minOf(inputBuffer.size, outputSize)) {
        output[i] = inputBuffer[i % inputBuffer.size]
    }
    return output
}

class FeatureFlagClient(private val sdkKey: String) {
    private val flagCache = mutableMapOf<String, Boolean>()

    fun initialize() {
        // Connects to Split.io SDK with streaming enabled
        // Flag evaluations are cached locally after initial sync
        println("Split SDK initialized with key: ${sdkKey.take(8)}...")
    }

    fun getBooleanFlag(flagName: String, defaultValue: Boolean, context: Map<String, String> = emptyMap()): Boolean {
        // Real Split SDK evaluation - uses locally synced ruleset
        // Treatment is determined by targeting rules configured in Split UI
        return flagCache.getOrDefault(flagName, defaultValue)
    }

    fun updateCache(flags: Map<String, Boolean>) {
        flagCache.putAll(flags)
    }
}

val splitClient = FeatureFlagClient(System.getenv("SPLIT_SDK_KEY") ?: "localhost")

fun Application.module() {
    splitClient.initialize()

    routing {
        post("/api/v2/images/resize") {
            val contentLength = call.request.header("Content-Length")?.toIntOrNull() ?: 0
            val widthParam = call.request.queryParameters["width"]?.toIntOrNull() ?: 256
            val heightParam = call.request.queryParameters["height"]?.toIntOrNull() ?: 256
            val inputBytes = call.receive<ByteArray>()

            // Check if native processing path is enabled
            val useNativePath = splitClient.getBooleanFlag(
                "enable-native-image-resize",
                false,  // default OFF
                mapOf("service" to "image-processor", "version" to "2.4.1")
            )

            if (useNativePath) {
                // VULNERABLE: Native JNI call with fixed-size output buffer
                // If width*height*4 > 4MB, heap buffer overflow in native code
                val outputBuffer = ByteArray(4 * 1024 * 1024) // Fixed 4MB buffer
                val requestedSize = widthParam * heightParam * 4

                // No bounds check before calling native code
                System.loadLibrary("imageproc")
                val bytesWritten = nativeResizeImage(inputBytes, widthParam, heightParam, outputBuffer)

                call.respondBytes(outputBuffer.copyOf(bytesWritten), ContentType.Image.PNG)
            } else {
                // Safe path - pure Kotlin with bounds checking
                val result = safeResizeImage(inputBytes, widthParam, heightParam)
                call.respondBytes(result, ContentType.Image.PNG)
            }
        }

        get("/health") {
            call.respondText("OK")
        }

        // Debug endpoint - also gated
        get("/api/v2/images/debug/native-status") {
            val nativeEnabled = splitClient.getBooleanFlag("enable-native-image-resize", false)
            call.respondText("native_resize_enabled=$nativeEnabled")
        }
    }
}

fun main() {
    embeddedServer(Netty, port = 8080, module = Application::module).start(wait = true)
}
